$ErrorActionPreference='Stop'
$stage='C:\Projects\gympro-staging'
$project='C:\Projects\gympro-api'
$git='C:\Program Files\Git\cmd\git.exe'
$started=$false;$success=$false;$captured=$false;$savedEnv=@{};$temporaryCreated=$false;$temporaryRemoved=$false
$utf8=New-Object Text.UTF8Encoding($false)
$meta=Get-Content (Join-Path $stage 'installation.json') -Raw|ConvertFrom-Json
$ready=Get-Content (Join-Path $stage 'ready.json') -Raw|ConvertFrom-Json
$bin=$meta.postgresBin;$node=$meta.nodeExe;$source=Join-Path $stage 'source';$cluster=Join-Path $stage 'pgdata'
$stamp=(Get-Date -Format 'yyyyMMddHHmmss')+'_'+[guid]::NewGuid().ToString('N').Substring(0,6)
$restore='gympro_stage_restore_'+$stamp
$report='C:\Projects\gympro-backups\local-staging-recovery-'+$stamp
function Run([string]$Exe,[string[]]$Arguments,[string]$Step){
 Write-Host "CHECK: $Step" -ForegroundColor Cyan
 $old=$ErrorActionPreference
 try{$ErrorActionPreference='Continue';& $Exe @Arguments;$code=$LASTEXITCODE}finally{$ErrorActionPreference=$old}
 [IO.File]::WriteAllText((Join-Path $report ($Step+'.exit-code.txt')),[string]$code)
 if($null -eq $code -or $code -ne 0){throw "Step failed: $Step (exit $code)"}
}
function Reveal([string]$Cipher){$s=ConvertTo-SecureString $Cipher;$p=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($s);try{return [Runtime.InteropServices.Marshal]::PtrToStringBSTR($p)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($p);$s.Dispose()}}
try{
 if($meta.databasePort -ne 55440 -or $meta.apiPort -ne 3200 -or $meta.sourceCommit -notmatch '^[a-f0-9]{40}$' -or $ready.passwordProtectedDatabaseVerified -ne $true){throw 'Unexpected or incomplete local staging installation.'}
 $sid=[Security.Principal.WindowsIdentity]::GetCurrent().User
 if($meta.installedBySid -ne $sid.Value){throw 'Use the Windows account that installed staging.'}
 foreach($port in @(3200,55440)){if(@(Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue).Count){throw "Stop staging first; port $port is occupied."}}
 if(Test-Path (Join-Path $cluster 'postmaster.pid')){throw 'Staging cluster PID file remains; inspect shutdown before recovery rehearsal.'}
 foreach($tool in @('pg_ctl.exe','pg_dump.exe','pg_dumpall.exe','pg_restore.exe','createdb.exe','dropdb.exe','psql.exe')){if(-not(Test-Path (Join-Path $bin $tool))){throw "Missing PostgreSQL tool: $tool"}}
 & $git -C $project cat-file -e ($meta.sourceCommit+'^{commit}')
 if($LASTEXITCODE -ne 0){throw 'Installed staging source commit is not available.'}
 New-Item -ItemType Directory $report|Out-Null
 $acl=New-Object Security.AccessControl.DirectorySecurity
 $acl.SetAccessRuleProtection($true,$false)
 foreach($identity in @($sid,([Security.Principal.SecurityIdentifier]::new('S-1-5-18')))){
  $acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($identity,[Security.AccessControl.FileSystemRights]::FullControl,[Security.AccessControl.InheritanceFlags]'ContainerInherit,ObjectInherit',[Security.AccessControl.PropagationFlags]::None,[Security.AccessControl.AccessControlType]::Allow))
 }
 $acl.SetOwner($sid);Set-Acl -LiteralPath $report -AclObject $acl
 $helper=Join-Path $report 'verify-recovery.mjs'
 [IO.File]::WriteAllBytes($helper,[Convert]::FromBase64String(''))
 Run $node @('--check',$helper) 'helper-syntax'
 Run $git @('-C',$project,'archive','--format=zip',('--output='+(Join-Path $report 'staging-source.zip')),$meta.sourceCommit) 'archive-installed-source'
 foreach($item in @(Get-ChildItem Env:)){if($item.Name -match '^(GYMPRO_|PG|PRISMA_|.*DATABASE_URL$|NODE_ENV$|NODE_OPTIONS$|PORT$)'){$savedEnv[$item.Name]=$item.Value;[Environment]::SetEnvironmentVariable($item.Name,$null,'Process')}}
 $captured=$true
 $credentials=Get-Content (Join-Path $stage 'credentials.dpapi.json') -Raw|ConvertFrom-Json
 $env:PGPASSWORD=Reveal $credentials.admin;$env:PGSSLMODE='disable'
 $started=$true
 Run (Join-Path $bin 'pg_ctl.exe') @('-D',$cluster,'-l',(Join-Path $report 'server.log'),'-o','-h 127.0.0.1 -p 55440','-w','start') 'start-owned-cluster'
 $identity=& (Join-Path $bin 'psql.exe') -X -w -h 127.0.0.1 -p 55440 -U postgres -d postgres -At -v ON_ERROR_STOP=1 -c 'SELECT (pg_control_system()).system_identifier::text;'
 if($LASTEXITCODE -ne 0 -or ($identity -join '').Trim() -ne $meta.systemIdentifier){throw 'Staging cluster identity/password mismatch.'}
 Run $node @($helper,$source,$stage,$report,'before') 'capture-source-fingerprints'
 $common=@('-w','-h','127.0.0.1','-p','55440','-U','postgres')
 $dump=Join-Path $report 'staging-database.dump'
 Run (Join-Path $bin 'pg_dump.exe') ($common+@('-d','gympro_saas','-Fc','-f',$dump)) 'dump-staging-database'
 Run (Join-Path $bin 'pg_restore.exe') @('--list','--file',(Join-Path $report 'archive-list.txt'),$dump) 'verify-archive-list'
 if((Get-Item $dump).Length -le 0 -or (Get-Item (Join-Path $report 'archive-list.txt')).Length -le 0){throw 'Backup or archive listing is empty.'}
 Run (Join-Path $bin 'pg_dumpall.exe') ($common+@('--roles-only','--no-role-passwords','-f',(Join-Path $report 'roles-without-passwords.sql'))) 'backup-roles-without-passwords'
 $roles=Get-Content (Join-Path $report 'roles-without-passwords.sql') -Raw
 if($roles -match "(?i)\bPASSWORD\s+'" -or $roles -match 'SCRAM-SHA-256\$'){throw 'Unexpected password material in role backup; inspect privately.'}
 Run (Join-Path $bin 'createdb.exe') ($common+@('--template=template0',$restore)) 'create-temporary-restore-database'
 $temporaryCreated=$true
 Run (Join-Path $bin 'pg_restore.exe') ($common+@('--exit-on-error','--single-transaction','-d',$restore,$dump)) 'restore-archive'
 Run $node @($helper,$source,$stage,$report,'verify',$restore) 'compare-restored-and-original'
 Run (Join-Path $bin 'dropdb.exe') ($common+@($restore)) 'remove-temporary-restore-database'
 $temporaryRemoved=$true
 $hashes=@('staging-database.dump','roles-without-passwords.sql','staging-source.zip')|ForEach-Object{
  $file=Join-Path $report $_
  [ordered]@{file=$_;sha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant();bytes=(Get-Item $file).Length}
 }
 $record=[ordered]@{scope='Local staging logical backup and same-cluster isolated database restore';installedSourceCommit=$meta.sourceCommit;databaseArchiveVerified=$true;passwordFreeRolesBackupCreated=$true;committedSourceArchiveCreated=$true;schemaSecurityAndOwnersMatch=$true;allTableFingerprintsAndSequencesMatch=$true;originalStagingContentUnchanged=$true;restoredUnknownSessionRejected=$true;temporaryDatabaseRemoved=$true;stagingApiStarted=$false;workingDatabaseUsed=$false;freshClusterRoleRestoreVerified=$false;crossMachineCredentialRecoveryVerified=$false;controlledUpdateRollbackVerified=$false;kbzPayDeferred=$true;files=$hashes;verifiedAt=(Get-Date -Format o)}
 [IO.File]::WriteAllText((Join-Path $report 'recovery-summary.json'),($record|ConvertTo-Json -Depth 8)+"`n",$utf8)
 $success=$true
}catch{Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red;Write-Host "Keep private reports/backups: $report";if($temporaryCreated -and -not $temporaryRemoved){Write-Host "Retained temporary restore database: $restore"};Write-Host 'Do not upload database backups or rerun blindly.'}finally{
 try{
  if($started -and (Test-Path (Join-Path $cluster 'postmaster.pid'))){
   Run (Join-Path $bin 'pg_ctl.exe') @('-D',$cluster,'-m','fast','-w','stop') 'stop-owned-cluster'
  }
 }catch{$success=$false;Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red}finally{
  if($captured){foreach($item in @(Get-ChildItem Env:)){if($item.Name -match '^(GYMPRO_|PG|PRISMA_|.*DATABASE_URL$|NODE_ENV$|NODE_OPTIONS$|PORT$)'){[Environment]::SetEnvironmentVariable($item.Name,$null,'Process')}};foreach($key in $savedEnv.Keys){[Environment]::SetEnvironmentVariable($key,$savedEnv[$key],'Process')}}
 }
 if(Test-Path $report){[ordered]@{completed=$success;temporaryDatabaseRemoved=$temporaryRemoved;stagingClusterStopped=(-not(Test-Path (Join-Path $cluster 'postmaster.pid')));reportFolder=$report}|ConvertTo-Json|Set-Content (Join-Path $report 'run-status.json') -Encoding UTF8}
}
if(-not $success){exit 1}
Write-Host 'PASS: Staging database archive, password-free role backup and committed source archive created.' -ForegroundColor Green
Write-Host 'PASS: Restored schema/security, data fingerprints, sequence values and session boundaries verified.'
Write-Host 'PASS: Temporary restore database removed; staging cluster stopped; original staging content preserved.'
Write-Host "Private recovery folder: $report"
Write-Host 'PENDING: Fresh-cluster/cross-machine credential recovery and controlled update/rollback.'
Write-Host 'No development database, staging application source, permissions, Git commit, dashboard completion claim or KBZPay changes.'
